@startuml

class Sober {}

class Car {
  + licensePlate : string
}

class Owner {
  + name : string
}

class Accident {
  + date : date
  + location : string
  + damageAmount : double
}

class Customer {
  + name : string
}

abstract class TaxiService {
  + pickUpTime : datetime
  + dropOffTime : datetime
  + pickUpLocation : string
  + dropOffLocation : string
  + rideDuration : string
  + distance : double
}

class RideHailing extends TaxiService {
  + requestType : string
  + fee : double
  + passengerCount : int
}

class RideSharing extends TaxiService {
  + upfrontNegotiatedFee : double
  + passengerCount : int
}

class RideHailingCustomer {
  + name : string
}

class RideSharingCustomer {
  + name : string
}

Sober "1" -- "*" Car
Sober "1" -- "*" Owner
Sober "1" -- "*" Customer
Car "1" -- "*" Accident
Car "1" -- "*" TaxiService
Owner "1" -- "0..*" Car
Customer "1" -- "*" RideHailingCustomer
RideHailing "1" -- "1" RideHailingCustomer : lead customer
RideHailing "1" -- "1..6" RideHailingCustomer : passengers
RideSharing "1" -- "1..10" RideSharingCustomer : passengers

@enduml

